item.content:encoded:
body {
	font-family: -apple-system, BlinkMacSystemFont, "Helvetica Neue", "Segoe UI", Roboto, Helvetica, Arial, "Hiragino Kaku Gothic ProN", "Hiragino Sans", "BIZ UDPGothic", Meiryo, sans-serif;
}

body a, .widget_fukasawa_recent_posts a:hover .title, .widget_fukasawa_recent_comments a:hover .title {
	transition: all 0.4s ease-in-out;
}

body a {
	color: #19838A;
}

code, kbd, pre {
	background: transparent;
	font-family: Menlo, Monaco, Consolas, monospace;
}

img.alignleft, .alignleft img, img.aligncenter, .aligncenter img, img.alignright, .alignright img, img.alignnone, .alignnone img {
	padding: 0;
	border: none;
}

pre {
	word-break: break-all;
}

sub, sup {
	font-size: 0.65em;
}

table, tbody {
	border: 2px solid #eee !important;
}

th, td {
	border: 1px solid #eee !important;
}

ul, ol {
	margin-bottom: 20px;
}

.blog-logo img {
	width: auto;
	height: auto;
}

.sidebar {
	border-bottom: none;
}

.post-overlay {
	background: transparent;
}

.post-overlay .view {
	display: none;
}

.post .post-title, .post.single .post-title, .post-content h2, .post-content h3, .post-content h4, .post-content h5 {
	font-feature-settings: "pkna";
	line-height: 140%;
}

.post-excerpt p {
  text-align: justify;
}

.post-excerpt > .wpulike {
	display: none;
}

.post-content .wp-caption-text, .post-content .gallery-caption, .post-content figcaption {
	font-size: 0.85em;
	line-height: 170%;
	font-style: normal;
}

.pr-message {
	color: #767676;
	font-size: 0.85em;
}

.post-excerpt p {
	font-style: normal;
}

.post.single .post-title {
	margin-bottom: 10px;
}

.post.page .post-title {
	margin-bottom: 40px;
}

.post-date-top {
	margin-bottom: 40px;
	color: #767676;
	font-size: 0.85em;
	font-weight: 700;
}

.post-content, .post-excerpt {
	overflow-wrap: break-word;
}

.post-content blockquote p {
	margin-bottom: 10px;
	font-family: "New York", "Cambria", "Georgia", YuMincho, "Hiragino Mincho ProN", "Yu Mincho", serif;
}

.post-content cite {
	font-weight: normal;
	text-transform: none;
	letter-spacing: 0;
}

.post-content input,
.post-content textarea { 
	font-family: -apple-system, BlinkMacSystemFont, "Helvetica Neue", "Segoe UI", Roboto, Helvetica, Arial, "Hiragino Kaku Gothic ProN", "Hiragino Sans", Meiryo, sans-serif;
}

.post-content kbd, .post-content code {
	padding: 0 3px;
}

.post-content li {
	margin: 5px 0;
}

.post-content table {
	margin: 0;
}

.post-content table tbody > tr:nth-child(odd) > th {
	background: #f9f9f9;
}

.post-content .caption {
	font-size: 0.85em;
  line-height: 170%;
  font-style: normal;
	color: #666;
	text-align: center;
}

.post-content .filename {
	margin-bottom: 0;
	padding: 0.3% 2.5% 0.2% 2.5%;
	border-radius: 6px 6px 0 0;
	background: #999;
	color: #fff;
	font-size: 0.8em;
	font-weight: 700;
	font-family: Menlo, Monaco, Consolas, monospace;
	word-break: break-all;
}

.post-content .filename + pre {
	margin-top: 0;
	border-radius: 0 0 6px 6px;
}

.post-content .mermaid {
background: transparent;
	text-align: center !important;
}

.post-content .mermaid .label {
	font-family: -apple-system, BlinkMacSystemFont, "Helvetica Neue", "Segoe UI", Roboto, Helvetica, Arial, "Hiragino Kaku Gothic ProN", "Hiragino Sans", Meiryo, sans-serif !important;
}

.post-content .mermaid .node rect,
.post-content .mermaid .node circle,
.post-content .mermaid .node ellipse,
.post-content .mermaid .node polygon,
.post-content .mermaid .node path {
  fill: #f2f2f2 !important;
	stroke: #666 !important;
}

.post-content .mermaid .edgeLabel {
  background-color: #fff !important;
  padding: 2px !important;
}

.post-content .mermaid .flowchart-link {
 stroke: #333 !important;
}

.post-content thead {
	white-space: normal;
}

.post-content .item th {
	width: 6em;
}

.post-content .item th {
	font-weight: normal;
	text-align: right;
	white-space: nowrap;
	vertical-align: top;
}

.post-content th, .post-content td {
	line-height: 170%;
}

.post-content p, .post-content blockquote, .post-content address, .post-content dl, .post-content .wp-caption, .post-content pre {
	margin-top: 30px;
	margin-bottom: 30px;
}

.post-content .wp-block-file, .post-content .wp-block-file__button,
.post-content .wp-block-button__link {
	font-family: -apple-system, BlinkMacSystemFont, "Helvetica Neue", "Segoe UI", Roboto, Helvetica, Arial, "Hiragino Kaku Gothic ProN", "Hiragino Sans", Meiryo, sans-serif;
}

.wp-block-table {
	margin: 30px 0;
}

.wp-block-archives, .wp-block-button, .wp-block-buttons, .wp-block-categories, .wp-block-code, .wp-block-columns, .wp-block-cover, .wp-block-cover-image, .wp-block-embed, .wp-block-gallery, .wp-block-group, .wp-block-image, .wp-block-latest-comments, .wp-block-latest-posts, .wp-block-media-text, .wp-block-preformatted, .wp-block-pullquote, .wp-block-social, .wp-block-quote, .wp-block-quote.is-large, .wp-block-quote.is-style-large, .wp-block-verse, .wp-block-video {
	margin: 30px 0;
}

.post-content .p50 {
	width: 50%;
	margin: auto;
}

.post-content .p75 {
	width: 75%;
	margin: auto;
}

.post-content .v-img {
	height: 620px;
}

.post-content .ref {
	font-size: 1em;
}

.wp-block-embed__wrapper {
	height: 100%;
}

.wp-embedded-content {
	width: 100%;
	min-height: 100%;
}

body:not(#__) .pochipp-box {
	margin: 30px 0;
}

.pochipp-box {
	padding: 20px !important;
	border: 2px solid #eee;
	box-shadow: none;
	color: #333;
	font-size: 1em;
}

@media (max-width: 600px) {
  .pochipp-box {
	  width: 100%;
  }
}

.pochipp-box__price {
	font-size: 0.85em;
}

.pochipp-box__price span {
	font-size: 0.85em;
}

[data-maxclmn-pc=fit]>.pochipp-box__btnwrap {
	font-size: 0.85em;
}

.pochipp-box[data-btn-style=dflt] .-paypay>.pochipp-box__btn {
	background-color: #48617f;
}

.post-meta-bottom {
	margin: 10px auto 50px;
}

.post-meta-bottom li a:hover {
	color: #21a4ac;
}

.wpulike {
	float: left;
	margin: 20px 0 0 0;
	padding: 0;
}

.wpulike-heart .wp_ulike_general_class {
	box-shadow: none;
	padding: 2px;
	border: 2px #ddd solid;
}

.wpulike .wp_ulike_btn:hover {
	opacity: .6;
	transition: all 0.4s ease-in-out;
}

.wpulike-heart .count-box {
	color: #666;
	font-size: 1em;
	font-weight: 700;
}

.heateor_sss_sharing_container {
	position: relative;
	top: -38px;
}

.heateor_sss_sharing_ul a {
	margin-left: 15px !important;
}

.heateor_sss_svg:hover {
	transition: all 0.4s ease-in-out !important;
}

.page-edit-post,
.post-edit-link {
	display: none;
}

.saboxplugin-wrap {
	margin-top: 50px;
}

.saboxplugin-wrap .saboxplugin-desc p {
	text-align: justify;
}

.saboxplugin-wrap .saboxplugin-authorname a {
	color: #333;
	font-weight: bold;
	letter-spacing: 3px;
}

.saboxplugin-wrap .saboxplugin-socials .saboxplugin-icon-grey {
	margin: 10px;
}

.saboxplugin-wrap .saboxplugin-authorname .sab-profile-edit, .sab-edit-settings {
	display: none;
}

.post-disclaimer {
	margin-top: 12px;
	color: #767676;
	font-size: 0.65em;
	line-height: 140%;
}

#jp-relatedposts {
	margin: 50px 0 0 0;
	padding-top: 0;
}

/* https://wordpress.org/support/topic/jetpack-related-posts-not-mobile-friendly/ */
@media only screen and (min-width:321px) and (max-width:640px){
  #jp-relatedposts .jp-relatedposts-items .jp-relatedposts-post:last-child {
    display: none;
  }
}

#jp-relatedposts .jp-relatedposts-items .jp-relatedposts-post {
	margin: 0;
}

@media only screen and (max-width:640px){
  #jp-relatedposts .jp-relatedposts-items-visual {
    margin-right: -20px !important;
  }
}

#jp-relatedposts .jp-relatedposts-items-visual .jp-relatedposts-post {
	opacity: 1;
	margin-bottom: 20px;
	font-weight: inherit;
}

#jp-relatedposts .jp-relatedposts-items-visual h4.jp-relatedposts-post-title {
	padding-top: 5px;
}

#jp-relatedposts .jp-relatedposts-items-visual .jp-relatedposts-post img.jp-relatedposts-post-img:hover {
	opacity: .6;
}

#jp-relatedposts .jp-relatedposts-items-visual .jp-relatedposts-post img.jp-relatedposts-post-img {
	transition: all 0.4s ease-in-out;
}

#jp-relatedposts .jp-relatedposts-items .jp-relatedposts-post:hover .jp-relatedposts-post-title a {
	text-decoration: none;
}

#jp-relatedposts .jp-relatedposts-items .jp-relatedposts-post .jp-relatedposts-post-title a {
	color: #333;
}

#jp-relatedposts .jp-relatedposts-items .jp-relatedposts-post .jp-relatedposts-post-title a:hover {
	color: #21a4ac;
}

.comment-form textarea, .searchform input[type="text"] {
	font-family: -apple-system, BlinkMacSystemFont, "Helvetica Neue", "Segoe UI", Roboto, Helvetica, Arial, "Hiragino Kaku Gothic ProN", "Hiragino Sans", Meiryo, sans-serif;
}

.widget-content li {
	padding: 5px 0;
	border-bottom: none;
}

.widget_tag_cloud a {
	background: transparent;
	border: 1px solid #e7e7e7;
}

.archive-nav {
	margin-top: 20px;
}

.archive-nav .archive-nav-button {
	width: 50%;
	padding: 0 10px;
}

.archive-nav a {
	display: block;
  position: relative;
  width: 100%;
  height: 120px;
	padding: 50px 0;
  overflow: hidden;
	border-bottom: 0px;
  background: #e2e2e2;
  color: #666;
  font-weight: 700;
  font-size: 14px;
  text-align: center;
  text-transform: uppercase;
  letter-spacing: 2px;
  transition: all 0.4s ease-in-out;
}

.archive-nav a:hover {
	background: #666;
	color: #fff;
}

@media (min-width: 830px) {
  .post-content p,
  .post-content li,
  .post-content blockquote,
  .post-content address,
  .post-content dl,
  .post-content .wp-caption {
  	text-align: justify;
  }
}

@media (max-width: 800px) {
  .archive-nav a {
  	max-height: 100px;
	  padding: 40px 0;
  }
}

@media (max-width: 600px) {
	.archive-nav {
		margin-top: 0;
	}

  .archive-nav .archive-nav-button {
		margin-top: 20px;
		width: 100%;
		padding: 0;
	}

  .archive-nav a {
  	max-height: 80px;
    width: 100%;
    margin: 0;
	  padding: 30px 0;
    float: none !important;
  }
}

.flag {
	margin-top: 30px;
	font-size: 1.5em;
}

@media (prefers-color-scheme: light) {

}

@media (prefers-color-scheme: dark) {
    :root {
        --base: #282c34;
        --mono-0: #dde1eb;
        --mono-1: #abb2bf;
        --mono-2: #818896;
        --mono-3: #5c6370;
        --mono-4: #404652;
        --mono-4-2: #343942;
        --hue-1: #56b6c2;
        --hue-2: #61aeee;
        --hue-3: #c678dd;
        --hue-4: #98c379;
        --hue-5: #e06c75;
        --hue-5-2: #be5046;
        --hue-6: #d19a66;
        --hue-6-2: #e6c07b;
        --theme-0: #29CED6;
        --theme: #21a4ac;
    }

    body,
    .post-navigation {
        background: var(--mono-4-2);
        color: var(--mono-0);
    }

    body a {
        color: var(--theme);
    }

    .posts .post-container > div,
    .post.single,
    .sidebar:before {
        background: var(--base);
    }

    .posts .post-title a,
    .post-content,
    .post-content blockquote,
    #jp-relatedposts .jp-relatedposts-items .jp-relatedposts-post .jp-relatedposts-post-title a,
    .saboxplugin-wrap .saboxplugin-authorname a,
    .main-menu a:hover,
    .main-menu .current-menu-item > a,
    .main-menu .current_page_item > a {
        color: var(--mono-0);
    }

  .page-title,
  .post-excerpt p,
  .post-content .wp-caption-text,
  .post-content .gallery-caption,
  .post-content figcaption,
 .post-content .caption,
  .post-navigation p,
  .main-menu a,
  .credits p,
  .credits p a,
  .widget_archive li a,
  .widget_categories li a,
  .widget_meta li a,
  .widget_nav_menu li a,
  .widget_pages li a,
  .widget-content,
  .widget_archive li:before,
  .widget_categories li:before,
  .widget_meta li:before,
  .widget_nav_menu li:before {
        color: var(--mono-1);
  }

    .post-content pre {
        background: var(--mono-4-2);
        color: var(--mono-0);
    }

    .post-content .filename {
        background: var(--mono-3);
        color: var(--mono-0);
    }

    .post-content table tbody > tr:nth-child(odd) > th,
    .post-content table tbody > tr:nth-child(odd) > td {
        background: var(--mono-4);
    }

    .post-content table tbody > tr:nth-child(even) > th,
    .post-content table tbody > tr:nth-child(even) > td {
        background: var(--mono-4-2);
    }

    .post-content th {
        color: var(--mono-0);
    }

table, tbody {
	border: 2px solid var(--mono-3) !important;
}

th, td {
	border: 1px solid var(--mono-3) !important;
}

	.post-content .mermaid .label {
		color: var(--mono-0) !important;
	}

  .post-content .mermaid .node rect,
  .post-content .mermaid .node circle,
  .post-content .mermaid .node ellipse,
  .post-content .mermaid .node polygon,
  .post-content .mermaid .node path {
  	fill: var(--mono-4) !important;
	  stroke: var(--mono-3) !important;
  }

  .post-content .mermaid .edgeLabel {
	  background-color: var(--base) !important;
}

	.post-content .mermaid .nodeLabel {
		color: var(--mono-0) !important;
	}

	.post-content .mermaid g.legend text {
		fill: var(--mono-0) !important;
	}

  .post-content .mermaid .flowchart-link {
	  stroke: var(--mono-2) !important;
  }

	.post-content .gist .blob-code-inner {
		color: var(--mono-0)  !important;
	}

	.gist .pl-c {
    color: var(--mono-2)  !important;
}

	.gist .pl-c1, .gist .pl-s .pl-v {
		color: var(--hue-1) !important;
	}

	.gist .pl-s, .gist .pl-pds, .gist .pl-s .pl-pse .pl-s1, .gist .pl-sr, .gist .pl-sr .pl-cce, .gist .pl-sr .pl-sre, .gist .pl-sr .pl-sra {
    color: var(--hue-2) !important;
}

	.gist .pl-e, .gist .pl-en {
    color: var(--hue-3) !important;
}

	.gist .pl-smi, .gist .pl-s .pl-s1 {
		color: var(--hue-4)  !important;
	}

	.gist .pl-k {
		color: var(--hue-5) !important;
	}

    .pochipp-box {
        border: 2px solid var(--mono-3);
        background: var(--base);
        color: var(--mono-0);
    }

    .post-meta-bottom:before {
        background: var(--mono-3);
    }

    .pr-message,
	  .post-date-top,
    .wpulike-heart .count-box,
    .post-meta-bottom,
    .post-meta-bottom li a {
        color: var(--mono-1);
    }


  .wpulike-heart .wp_ulike_general_class {
     border: 2px solid var(--mono-3);
  }

	.post-disclaimer {
    color: var(--mono-2);
	}

  .heateor_sss_horizontal_sharing .heateor_sss_svg {
    background-color: var(--mono-2) !important;
  }
	.heateor_sss_horizontal_sharing .heateor_sss_svg:hover {
		background-color: #21a4ac !important;
	}

	.heateor_sss_horizontal_sharing .heateor_sss_svg path {
		fill: var(--base);
	}

    .saboxplugin-wrap {
        border: 2px solid var(--mono-3);
    }

    .saboxplugin-wrap .saboxplugin-socials {
        background: var(--mono-4-2);
        border-top: 2px solid var(--mono-3);
    }

    .saboxplugin-wrap .saboxplugin-socials .saboxplugin-icon-grey {
        color: var(--mono-1);
        fill: var(--mono-1);
    }

    .main-menu:before, .widgets:before,
    .widget + .widget:before,
    .credits:before {
        background: var(--mono-3);
    }

    .wp-block-search.wp-block-search__button-inside .wp-block-search__inside-wrapper {
        border: 1px solid var(--mono-2);
    }

    input[type=search] {
        background: var(--base);
        color: var(--mono-1);
    }

    .wp-block-search__button {
        border: 1px solid var(--mono-4);
		  	background: var(--mono-4-2);
        color: var(--mono-2);
    }

		.widget_tag_cloud a {
				background: transparent;
				color: var(--mono-1);
				border: 1px solid var(--mono-3);
		}

    .archive-nav a,
    .post-navigation a {
        background: var(--mono-4);
        color: var(--mono-1);
    }

    .archive-nav a:hover,
    .post-navigation a:hover {
        background: var(--mono-3);
    }

    .nav-toggle p {
        color: var(--mono-1);
    }

    .nav-toggle .bar {
        background: var(--mono-1);
    }

    .nav-toggle.active p {
        color: var(--mono-4-2);
    }

    .nav-toggle.active .bar {
        background: var(--mono-4-2);
    }

    .mobile-navigation {
        background: var(--mono-1);
    }

    .mobile-menu > .current-menu-item > a,
    .mobile-menu > .current_page_item > a {
        color: var(--base);
    }

    .mobile-menu a {
        color: var(--mono-3);
    }

    .archive-title {
        border-bottom-color: var(--mono-3);
    }

    @media (max-width: 1000px) {
        .sidebar {
            background: var(--base);
            color: var(--mono-1);
        }
    }
}

/* Notion-like callouts for WordPress, by Verfasor */
 .callout {
     border-radius: 10px;
     padding: 1em;
}
 @media (prefers-color-scheme: light) {
     .grey_callout {
         background: rgb(241, 241, 239);
    }
     .brown_callout {
         background: rgb(244, 238, 238);
    }
     .orange_callout {
         background: rgb(251, 236, 221);
    }
     .yellow_callout {
         background: rgb(251, 243, 219);
    }
     .green_callout {
         background: rgb(237, 243, 236);
    }
     .blue_callout {
         background: rgb(231, 243, 248);
    }
     .purple_callout {
         background: rgba(244, 240, 247, 0.8);
    }
     .pink_callout {
         background: rgba(249, 238, 243, 0.8);
    }
     .red_callout {
         background: rgb(253, 235, 236);
    }
}
 @media (prefers-color-scheme: dark) {
     .callout {
         color: white;
    }
     .grey_callout {
         background: rgba(124,139,154,.13);
    }
     .brown_callout {
         background: rgb(55, 34, 13);
    }
     .orange_callout {
         background: rgb(71, 45, 1);
    }
     .yellow_callout {
         background: rgba(240,165,15,.13);
    }
     .green_callout {
         background: rgba(52,183,67,.12);
    }
     .blue_callout {
         background: rgba(33,172,232,.12);
    }
     .purple_callout {
         background: rgba(135,85,236,.12);
    }
     .pink_callout {
         background: rgba(225,71,174,.11);
    }
     .red_callout {
         background: rgba(209,46,46,.11);
    }
}
/* Notion-like callouts for WordPress, by Verfasor */
